def tone_words(t: dict) -> str:
    pick = lambda v, lo, mid, hi: lo if v < 0.34 else (mid if v < 0.67 else hi)
    return " ".join([
        pick(t["formal"], "Casual and plain-spoken.", "Natural and clear.", "Formal and precise."),
        pick(t["warmth"], "Blunt; no cushioning.", "Friendly but direct.", "Warm and encouraging."),
        pick(t["detail"], "Brief: get to the point.", "Enough detail to be useful.", "Thorough: explain the why."),
        pick(t["bold"], "Cautious; flag risks.", "Balanced.", "Bold; give a clear call."),
        pick(t["playful"], "Serious.", "A light touch.", "Playful, with humour."),
    ])


def compile_spec(p: dict) -> str:
    """A short, distinct character prompt in the personality's own terms (no shared template)."""
    ex = "\n".join(f"User: {u}\nAria: {a}" for u, a in p["examples"])
    lines = [
        f"You are Aria, speaking as {p['name']}: {p['role']}.",
        f"Expertise: {p['expertise']}. You keep coming back to: {', '.join(p['focus'])}.",
        f"How you think: {', '.join(p['frameworks'])}.",
        f"How you sound: {tone_words(p['tone'])} Sentences: {p['sentences']}."
        + (" Ask a question back when it helps." if p["asks_questions"] else ""),
        "Phrases you sometimes use (at most one per reply, and only where it fits naturally): "
        + "; ".join(f'"{x}"' for x in p["phrases"]) + ".",
        "Bring your own angle to every answer, even general questions: answer through your expertise and focus.",
        "Always: " + "; ".join(p["dos"]) + ".",
        "Never: " + "; ".join(p["donts"]) + ".",
    ]
    lines.append("Answers: " + {"short": "usually one to three sentences, never more than four unless asked for detail",
                               "medium": "usually three to five sentences, never more than six unless asked for detail",
                               "long": "longer, structured explanations when the question deserves it"}[p["length"]]
                 + ". Tables or diagrams on screen: " + {"rarely": "rarely", "sometimes": "only when they clearly help",
                                                          "often": "readily, for comparisons, steps and numbers"}[p["rich"]] + ".")
    if p.get("disclaimer"):
        lines.append(f"When it matters, say briefly: {p['disclaimer']}")
    lines.append("Your voice, for example (tone only; not facts about this user):\n" + ex)
    return "\n".join(lines)


def main():
    out = sys.argv[1]
    for p in ITEMS:
        p["text"] = ("LANGUAGE: fr\n" if p["id"] == "frenchtutor" else "") + compile_spec(p)
    json.dump({"version": 2, "items": ITEMS}, open(out, "w"), indent=1, ensure_ascii=False)
    print(len(ITEMS), "personalities")


if __name__ == "__main__":
    main()
